        ],['Το demo είναι όμορφο, αλλά η φόρμα δεν στέλνει και ο πελάτης λέει «μου αρέσει».','Καταγράφεις το θετικό feedback χωρίς να δηλώνεις ολοκληρωμένη παράδοση. Η βασική λειτουργία διορθώνεται και επανελέγχεται, ενώ η εμπορική αποδοχή ακολουθεί τους εγκεκριμένους όρους.']]
    ];
    $out=[];
    foreach ($rows as $id=>[$pillar,$title,$goal,$sections,$scenario]) {
        $words=0; foreach($sections as [, $paragraphs])$words+=count(preg_split('/\s+/u',implode(' ',$paragraphs),-1,PREG_SPLIT_NO_EMPTY));
        $out[$id]=['pillar'=>$pillar,'title'=>$title,'goal'=>$goal,'sections'=>$sections,'scenario'=>$scenario,'minutes'=>(int)ceil($words/130)+4,'version'=>1,'quiz'=>[],
            'source_note'=>'Σύνθεση από το Call Center Website Sales Training Manual, το «Πάμε» και την «Εκπαίδευση τηλεφωνικού κέντρου». Τα παραδείγματα είναι εκπαιδευτικά· δεν θεσπίζουν τιμές, άδειες ή νέες λειτουργίες CRM.'];
